#!/usr/bin/env python3
"""Apply reviewed Sites v8 UI changes. No data/model/H2H assets are replaced."""
import base64, hashlib, json, lzma, re, subprocess
from pathlib import Path
PAYLOAD = ""
DIGEST = "bf9edab8ca5b4e091ff2702d9dfd3ca6f7ee26ebb0a8bb38b040c475c8d613dc"
ALLOWED = {'index.html','assets/home-sections.css','assets/home-sections.js','assets/pick-tracker-dashboard.css','assets/pick-tracker.js','pick-tracker.html','scripts/check_pick_tracker.js','scripts/test_pick_tracker.js'}
def sha(text): return hashlib.sha256(text.encode()).hexdigest()
def main():
    raw=lzma.decompress(base64.b64decode(PAYLOAD))
    assert hashlib.sha256(raw).hexdigest()==DIGEST, 'Migration payload corrupted'
    patches=json.loads(raw)
    assert set(patches)==ALLOWED
    protected=list(Path('data').rglob('*.json'))+[Path(p) for p in ['assets/player-game-log.js','assets/player-game-log.css','assets/homepage-feed.js','assets/homepage-score-source.js','assets/projection-safety.js','assets/projection-trial.js','scripts/projection_trial.py','scripts/refresh_projection_feed.py','projections-2026.html','projection-trial.html']]
    hashes={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in protected}
    inline=lambda s:[x for x in re.findall(r'<script\b[^>]*>([\s\S]*?)</script>',s) if x.strip()]
    old_inline=inline(Path('index.html').read_text())
    outputs={}
    for name,p in patches.items():
        path=Path(name); source=path.read_text(encoding='utf-8') if path.exists() else ''
        if sha(source)==p['sha']: continue
        if 'new' in p:
            assert not path.exists(), 'Unreviewed existing file: '+name
            result=p['new']
        else:
            assert sha(source)==p['before'], 'Newer file needs reconciliation: '+name
            result=source
            for start,end,text in reversed(p['ops']): result=result[:start]+text+result[end:]
        assert sha(result)==p['sha'], 'Unexpected result: '+name
        outputs[name]=result
    for name,result in outputs.items():
        path=Path(name);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(result,encoding='utf-8')
    assert inline(Path('index.html').read_text())==old_inline, 'Homepage app changed'
    for name,digest in hashes.items(): assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==digest, name+' changed'
    for name in ['assets/pick-tracker.js','assets/home-sections.js','scripts/check_pick_tracker.js']:
        subprocess.run(['node','--check',name],check=True)
    subprocess.run(['node','scripts/test_pick_tracker.js'],check=True)
    subprocess.run(['node','scripts/test_projection_safety.js'],check=True)
    report={'source':'Gridiron-Pulse-GitHub-Pages-v8.zip','sourceZipSha256':'07ce7d0bf29f8c9615442efd3f6621723013a34b4223cbf8aff02f75358a1bf0','homepageInlineScriptsUnchanged':True,'protectedFilesUnchanged':len(hashes),'changedFiles':sorted(outputs),'buildKey':'20261002-sites-v8'}
    Path('sites-v8-preservation.json').write_text(json.dumps(report,indent=2))
    print(json.dumps(report,indent=2))
if __name__=='__main__': main()
